		{
			name: "new: package 1",
			args: args{line: "gpg-pubkey 0 f5282ee4 58ac92a3 (none) (none)"},
			wantbp: &models.Package{
				Name:    "gpg-pubkey",
				Version: "f5282ee4",
				Release: "58ac92a3",
