		{
			name: "modularity: package 1",
			args: args{line: "dnf 0 4.14.0 1.fc35 noarch dnf-4.14.0-1.fc35.src.rpm (none)"},
			wantbp: &models.Package{
				Name:    "dnf",
				Version: "4.14.0",
				Release: "1.fc35",
				Arch:    "noarch",
