func (o *redhatBase) parseUpdatablePacksLine(line string) (models.Package, error) {
	// repoquery separates the fields with a single space. Consume only one
	// separator after the version so an empty release is not lost.
	rest := strings.TrimLeft(line, " \t")
	var fields [3]string
	for i := range fields {
		end := strings.IndexAny(rest, " \t")
		if end <= 0 {
			return models.Package{}, xerrors.Errorf("Unknown format: %s", line)
		}
		fields[i] = rest[:end]
		if i < len(fields)-1 {
			rest = strings.TrimLeft(rest[end:], " \t")
		} else {
			rest = rest[end+1:]
		}
	}

	releaseEnd := strings.IndexAny(rest, " \t")
	if releaseEnd < 0 {
		return models.Package{}, xerrors.Errorf("Unknown format: %s", line)
	}
	release := rest[:releaseEnd]
	repository := strings.TrimSpace(rest[releaseEnd+1:])
	if repository == "" {
		return models.Package{}, xerrors.Errorf("Unknown format: %s", line)
	}

	version := fields[2]
	if fields[1] != "0" && fields[1] != "(none)" {
		version = fmt.Sprintf("%s:%s", fields[1], version)
	}

	return models.Package{
		Name:       fields[0],
		NewVersion: version,
		NewRelease: release,
		Repository: repository,
	}, nil
}

