// splitFileName returns a name, version, release, epoch, arch:
//
//	e.g.
//		foo-1.0-1.i386.rpm => foo, 1.0, 1, i386
//		1:bar-9-123a.ia64.rpm => bar, 9, 123a, 1, ia64
//
// https://github.com/rpm-software-management/yum/blob/043e869b08126c1b24e392f809c9f6871344c60d/rpmUtils/miscutils.py#L301
func splitFileName(filename string) (name, ver, rel, epoch, arch string, err error) {
	invalid := func() (string, string, string, string, string, error) {
		return "", "", "", "", "", xerrors.Errorf("unexpected file name. expected: %q, actual: %q", "<name>-<version>-<release>.<arch>.rpm", filename)
	}
	if !strings.HasSuffix(filename, ".rpm") {
		return invalid()
	}
	basename := strings.TrimSuffix(filename, ".rpm")

	// Some source RPMs use "-src.rpm" in place of ".src.rpm".
	var nvr string
	if strings.HasSuffix(basename, "-src") {
		arch, nvr = "src", strings.TrimSuffix(basename, "-src")
	} else {
		archIndex := strings.LastIndex(basename, ".")
		if archIndex == -1 {
			return invalid()
		}
		arch, nvr = basename[archIndex+1:], basename[:archIndex]
	}
	if arch == "" || strings.ContainsAny(arch, "-./\\ \t\r\n") {
		return invalid()
	}

	relIndex := strings.LastIndex(nvr, "-")
	if relIndex == -1 {
		return invalid()
	}
	rel = nvr[relIndex+1:]
	nameVersion := nvr[:relIndex]
	verIndex := strings.LastIndex(nameVersion, "-")
	if verIndex == -1 {
		return invalid()
	}
	name, ver = nameVersion[:verIndex], nameVersion[verIndex+1:]
	if name == "" || ver == "" || strings.HasPrefix(name, "-") || strings.HasSuffix(name, "-") || strings.ContainsAny(name+ver+rel, "/\\ \t\r\n") || strings.ContainsAny(ver+rel, ":") {
		return invalid()
	}
	if prefix, rest, hasEpoch := strings.Cut(name, ":"); hasEpoch {
		if prefix == "" || rest == "" || strings.HasPrefix(rest, "-") || strings.HasSuffix(rest, "-") || strings.Trim(prefix, "0123456789") != "" || strings.Contains(rest, ":") {
			return invalid()
		}
		epoch, name = prefix, rest
	}
	return name, ver, rel, epoch, arch, nil
}

